/**
 * @method
 * @name img_Etnlist_OnSelChanged
 * @description img Etnlist On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Etnlist_OnSelChanged = async function(nIndex) {
    try {
        if (nIndex === 1) {
            await scwin.search();
        }
        if (nIndex === 2) // ko_jackal_10.06.15

        {
            rdo_ISUR_CD_1.setValue("1");
            rdo_ISUR_CD_2.setValue("2");
            txb_ISU_CD.setValue("");
            txb_ISU_NM.setValue("");
            cmb_ISUR_CD.setSelectedIndex(0);

            // fn_search2();

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08054.img_Etnlist_OnSelChanged" });
    }
};

/**
