///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description jackal_11.05.12 상장종목 여부 체크 추가
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&SCREN_ID=" + "ULDSTF08054.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts",
        action : "/etn/EtnMktAct.do",
        ref : "",
        target : "dts=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search2
 * @description search2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search2 = async function() {
    if (rdo_ISUR_CD_1.getValue() === "1") {
        if (txb_ISU_CD.getValue() === "") {
            url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_ALL_INFO + "&TRS_IDX=" + TRS_IDX_SELECT + "&GUBUN_CD=ETN";
        } else {
            url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_ISU_INFO + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISU_CD=" + txb_ISU_CD.getValue();
        }
    } else if (rdo_ISUR_CD_2.getValue() === "1") {
        if (cmb_ISUR_CD.getSelectedIndex() === 0) {
            url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_ALL_INFO + "&TRS_IDX=" + TRS_IDX_SELECT + "&GUBUN_CD=ETN";
        } else {
            url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_CORP_INFO + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + cmb_ISUR_CD.BindColVal;
        }
    }
    const sbmOptions = {
        id : "sbm_dts2",
        action : "/etn/EtnMktAct.do",
        ref : "",
        target : "dts2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getIsurcode
 * @description etn발행사
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getIsurcode = async function() {
    // etn발행사
    const sbmOptions = {
        id : "sbm_dts_EtnInst",
        action : "/etn/EtnCodeAct.do",
        ref : "",
        target : "dts_EtnInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

